import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import { Mensaje, CreateMensajePayload, UpdateMensajePayload } from '../models/mensaje.model';
import { environment } from '../../../environments/environment';

@Injectable({ providedIn: 'root' })
export class MensajeService {
  private readonly http = inject(HttpClient);

  getMensajes(folio: string): Observable<Mensaje[]> {
    return this.http.get<{ data: Mensaje[] }>(`${environment.apiUrl}/solicitudes/${folio}/mensajes`)
      .pipe(map(response => response.data));
  }

  getNotas(folio: string, page = 1, perPage = 15): Observable<{ data: Mensaje[]; meta: Record<string, unknown> }> {
    const params = new HttpParams()
      .set('page', page.toString())
      .set('per_page', perPage.toString());

    return this.http.get<{ data: Mensaje[]; meta: Record<string, unknown> }>(
      `${environment.apiUrl}/solicitudes/${folio}/mensajes/notas`,
      { params },
    );
  }

  getChatMensajes(folio: string, after?: number): Observable<Mensaje[]> {
    let params = new HttpParams();
    if (after !== undefined) {
      params = params.set('after', after.toString());
    }

    return this.http.get<{ data: Mensaje[] }>(
      `${environment.apiUrl}/solicitudes/${folio}/mensajes/chat`,
      { params },
    ).pipe(map(response => response.data));
  }

  createMensaje(folio: string, payload: CreateMensajePayload): Observable<Mensaje> {
    return this.http.post<{ data: Mensaje }>(
      `${environment.apiUrl}/solicitudes/${folio}/mensajes`,
      payload,
    ).pipe(map(response => response.data));
  }

  updateMensaje(id: number, payload: UpdateMensajePayload): Observable<Mensaje> {
    return this.http.put<{ data: Mensaje }>(
      `${environment.apiUrl}/mensajes/${id}`,
      payload,
    ).pipe(map(response => response.data));
  }

  deleteMensaje(id: number): Observable<void> {
    return this.http.delete<void>(`${environment.apiUrl}/mensajes/${id}`).pipe(
      map(() => undefined),
    );
  }

  adjuntarDocumento(mensajeId: number, documentoId: number): Observable<Mensaje> {
    return this.http.post<{ data: Mensaje }>(
      `${environment.apiUrl}/mensajes/${mensajeId}/adjuntar`,
      { documento_id: documentoId },
    ).pipe(map(response => response.data));
  }
}
